namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string CourseCode { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be in format: XX000000 (2 letters followed by 6 digits).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(int id);
    IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "The science of numbers, quantity, and space." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Title = "Introduction to Programming", CourseCode = "CS 101", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design principles. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of teaching experience and specializes in programming language design. She holds a PhD from MIT and has published extensively on developer education.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, Title = "Data Structures & Algorithms", CourseCode = "CS 201", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez is an ACM Distinguished Scientist whose research focuses on algorithm optimization. He previously worked at Google Research.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, Title = "Database Systems", CourseCode = "CS 340", Description = "Relational database design, SQL, normalization, transaction processing, and introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Prof. Maria Santos", InstructorBio = "Prof. Santos spent a decade as a database architect at Oracle before joining academia. Her courses blend theory with industry practice.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, Title = "Calculus I", CourseCode = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an award-winning educator known for making calculus accessible. He has authored two bestselling textbooks.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
        new() { Id = 5, Title = "Linear Algebra", CourseCode = "MATH 220", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to data science and machine learning.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Nina Patel", InstructorBio = "Dr. Patel's research bridges pure mathematics and machine learning. She consults for several AI startups.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 6, Title = "Classical Mechanics", CourseCode = "PHYS 201", Description = "Newtonian mechanics, conservation laws, oscillations, and rotational dynamics. Calculus-based.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is a former NASA researcher with expertise in orbital mechanics. He brings real-world space mission examples to the classroom.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 7, Title = "Quantum Physics", CourseCode = "PHYS 350", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Dr. Elena Vasquez", InstructorBio = "Dr. Vasquez conducts research in quantum computing at the university's advanced physics lab. She has published over 50 papers in Nature Physics.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
        new() { Id = 8, Title = "Creative Writing", CourseCode = "ENG 210", Description = "Workshop-based exploration of fiction, poetry, and creative nonfiction. Develop your unique voice through peer critique and revision.", Credits = 3, Schedule = "Wed 6:00–8:50 PM", InstructorName = "Prof. Michael Torres", InstructorBio = "Prof. Torres is a published novelist and National Book Award finalist. His fiction has appeared in The New Yorker and Harper's.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 9, Title = "American Literature", CourseCode = "ENG 305", Description = "Survey of American literary works from the colonial period to the present. Examines themes of identity, freedom, and social change.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Angela Washington", InstructorBio = "Dr. Washington specializes in African American literature and has received multiple teaching excellence awards.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 10, Title = "World History: 1500–Present", CourseCode = "HIST 102", Description = "Global history from the Age of Exploration through the modern era. Covers colonialism, revolutions, world wars, and globalization.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Okafor", InstructorBio = "Dr. Okafor is a historian of global empires with fieldwork experience across three continents. He previously taught at Oxford.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
    ];

    public IReadOnlyList<Department> GetDepartments() => Departments;

    public Department? GetDepartment(int id) => Departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => Courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return GetCourse(request.CourseId) is not null;
    }
}

